import {NumberReadOnlyExpression} from "./numberExpression";
import {MaybeReadOnlyExpression} from "./maybeExpression";
import {ConditionReadOnlyExpression} from "./conditionExpression";

/**
 * A list-maker lambda: returns the set of numbers (or sub-blueprints) the
 * blueprint is built over. Evaluated at generateValue()/isGeneratedBy() time so
 * the set can be produced dynamically (it can reach the live hostApi through its
 * enclosing scope). Accepts fixed numbers, NumberReadOnlyExpressions (including a
 * sub-blueprint's generateValue() grammar), or sub-blueprints directly.
 */
export type NumberBlueprintListMaker = () => Array<number | NumberReadOnlyExpression | NumberBlueprint>;

/**
 * NumberBlueprint — a composable grammar over a set of integers, represented as
 * a union of inclusive integer ranges ("pieces"). It generates a random integer
 * from its language (drawn from the shared seeded LXM stream) and tests whether a
 * given integer could have been generated by it. See numberBlueprint.js.
 */
export type NumberBlueprintApi = {
  /**
   * Language = union of the elements' integer sets. Takes a list-maker lambda
   * `() => Array<number | NumberReadOnlyExpression | subBlueprint>`, evaluated at
   * generateValue()/isGeneratedBy() time so the set (and any generated values)
   * can be produced dynamically.
   */
  oneOf: (makeList: NumberBlueprintListMaker) => NumberBlueprint;

  /**
   * Language = the single inclusive integer interval [fromInclusive, toInclusive],
   * drawn from the seeded LXM stream. An empty interval (from > to) yields an
   * empty language.
   */
  range: (fromInclusive: NumberReadOnlyExpression | number, toInclusive: NumberReadOnlyExpression | number) => NumberBlueprint;

  /** Marker for HostApi surfaces */
  type: NumberBlueprintType,
}

export type NumberBlueprintType = {
  // used when declaring argument types dynamically in HostApi clients
}

export type NumberBlueprint = {
  /**
   * The blueprint -> NumberReadOnlyExpression conversion. Present (maybe.of) with
   * a random integer from the language when it is non-empty; absent (maybe.none)
   * for an empty language.
   */
  generateValue: () => MaybeReadOnlyExpression<NumberReadOnlyExpression>;

  /**
   * Membership as a condition: true iff `candidate` (evaluated to a concrete
   * integer) is a member of this blueprint's language.
   */
  isGeneratedBy: (candidate: NumberReadOnlyExpression | number) => ConditionReadOnlyExpression<NumberReadOnlyExpression>,
}
